// The marine character pack: twelve original shapes, their eye layouts and the paint
// palette, plus the SVG renderer the client uses for Bot marks and avatars. The data is
// the final asset pack for `assets/marine/`; the renderer puts the eyes on a foreground
// layer so they stay white and dark-blue on any theme.
//
// This module is data and pure rendering only: no DOM, no React, no network.

/// One eye of a creature: its white shape, pupil and closed-eye path, drawn on a
/// foreground layer above the body.
export interface MarineEye {
	/** Stable id of the eye inside its creature, used for tests and diagnostics. */
	id?: string;
	/** SVG path data of the white of the eye. */
	white: string;
	/** Where the eye sits in the 100x100 viewBox; used for the gaze anchor. */
	center: number[];
	/** SVG path data of the pupil, clipped by the white. Empty when the shape has none. */
	pupil: string;
	/** SVG path data of the closed eye. */
	blink: string;
	/** Bounding box [x, y, width, height] in the 100x100 viewBox, as shipped. */
	bounds?: number[];
}

/** One marking drawn in white above the body. */
export interface MarineMarking {
	/** What the marking is for, as recorded in the asset pack. */
	role?: string;
	d: string;
}

/** One of the twelve marine characters. */
export interface MarineCreature {
	id: string;
	label: string;
	orientation: string;
	body: string;
	markings: MarineMarking[];
	eyes: MarineEye[];
	/** Where the shape came from in the asset pack; informational only. */
	provenance?: string;
}

/** One paint token: the fill per theme, plus the gradient stops for the aurora color. */
export interface MarinePaletteToken {
	id: string;
	/** Human label from the asset pack. */
	label?: string;
	light: string;
	dark: string;
	stops?: [number, string][];
}

/** What `renderMarineMark` and `renderMarineSvg` accept. */
export interface MarineOptions {
	color?: string;
	theme?: "light" | "dark";
	prefix?: string;
	blink?: boolean;
	gaze?: [number, number];
	size?: number;
}

