export const DEFAULT_LOOK = { shape: "marine-whale", color: "deepseek" };
let serial = 0;
const esc = (v: unknown): string =>
	String(v).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
const safeId = (v: unknown): string => String(v).replace(/[^a-zA-Z0-9_-]/g, "-");
const paths = (d: string): string => (d.match(/M[^M]*/g) || [d]).map((x) => '<path d="' + esc(x) + '"/>').join("");
export function renderMarineMark(
	shapeId: string,
	{ color = "deepseek", theme = "light", prefix, blink = false, gaze = [0, 0] }: MarineOptions = {},
): string {
	const def = CREATURES.find((x) => x.id === shapeId);
	if (!def) throw new Error("Unknown marine shape: " + shapeId);
	const key = safeId(prefix || shapeId + "-" + ++serial);
	const token = PALETTE.find((x) => x.id === color);
	if (!token && !/^#[0-9a-f]{6}$/i.test(color)) throw new Error("Color must be a palette id or six-digit hex");
	const fill = token ? token[theme === "dark" ? "dark" : "light"] : color;
	const gradient = token?.stops
		? '<linearGradient id="' +
			key +
			'-paint" x1="0" y1="0" x2="1" y2="1">' +
			token.stops.map(([o, c]) => '<stop offset="' + o + '" stop-color="' + c + '"/>').join("") +
			"</linearGradient>"
		: "";
	const gx = Math.max(-0.65, Math.min(0.65, Number(gaze[0]) || 0)),
		gy = Math.max(-0.65, Math.min(0.65, Number(gaze[1]) || 0));
	const defs = def.eyes
		.map((e, i) => '<clipPath id="' + key + "-eye-" + i + '">' + paths(e.white) + "</clipPath>")
		.join("");
	const eyeMarkup = def.eyes
		.map(
			(e, i) =>
				'<g class="mb-eye" data-eye-index="' +
				i +
				'" data-anchor="' +
				e.center.join(" ") +
				'">' +
				(blink
					? '<path class="mb-eye-closed" d="' +
						esc(e.blink) +
						'" fill="none" stroke="#FFFFFF" stroke-width="1.7" stroke-linecap="round"/>'
					: '<g class="mb-eye-open"><g fill="#FFFFFF">' +
						paths(e.white) +
						"</g>" +
						(e.pupil
							? '<g clip-path="url(#' +
								key +
								"-eye-" +
								i +
								')"><g fill="#172B4D" transform="translate(' +
								gx +
								" " +
								gy +
								')">' +
								paths(e.pupil) +
								"</g></g>"
							: "") +
						"</g>") +
				"</g>",
		)
		.join("");
	return (
		"<defs>" +
		gradient +
		defs +
		'</defs><g class="mb-body" data-layer="body" fill="' +
		(gradient ? "url(#" + key + "-paint)" : fill) +
		'" fill-rule="nonzero">' +
		paths(def.body) +
		'</g><g class="mb-markings" data-layer="markings" fill="#FFFFFF">' +
		def.markings.map((x) => paths(x.d)).join("") +
		'</g><g class="mb-eyes" data-layer="eyes">' +
		eyeMarkup +
		"</g>"
	);
}
export function renderMarineSvg(shapeId: string, options: MarineOptions = {}): string {
	const def = CREATURES.find((x) => x.id === shapeId);
	if (!def) throw new Error("Unknown marine shape");
	const size = Number.isFinite(options.size) && (options.size ?? 0) > 0 ? (options.size as number) : 128;
	const key = safeId(options.prefix || shapeId + "-" + ++serial);
	return (
		'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="' +
		size +
		'" height="' +
		size +
		'" role="img" aria-labelledby="' +
		key +
		'-title"><title id="' +
		key +
		'-title">' +
		esc(def.label) +
		"</title>" +
		renderMarineMark(shapeId, { ...options, prefix: key }) +
		"</svg>"
	);
}
